mapper.delete:
DELETE FROM TB_PM30M01
WHERE CO_CD = #{coCd, jdbcType=VARCHAR}
  AND WORK_DT = #{workDt, jdbcType=VARCHAR}
  AND EMP_NO = #{empNo, jdbcType=VARCHAR}

mapper.select:
SELECT EMP_NO, SRC_TYPE, APPL_NO, RPT_NO, ST_DT, ED_DT, TRIP_TYPE_CDS, TRIP_TYPE_NM, TRIP_PLACE, TRIP_DIV, TRIP_DIV_NM, EQUIP_NM, CLNT_PJT, CLNT_PJT_NM, SALES_CD, ORDRS_NO, VAC_TYPE_CD, VAC_TYPE_NM, AMPM_CD, WORK_HOUR, STS FROM ( -- 1) 출장(복명서 있는 경우: 실제일시, TB_PM52D02 기준, 출장자별 개별행) SELECT /*+ LEADING(U D M D3) USE_NL(D M D3) INDEX(D) PUSH_PRED(D3) */ U.EMP_NO AS EMP_NO, 'TRIP_RPT' AS SRC_TYPE, M.TRIP_REQ_NO AS APPL_NO, M.TRIP_RPT_NO AS RPT_NO, SUBSTR(D.TRIP_ST_DTM, 1, 8) AS ST_DT, SUBSTR(D.TRIP_ED_DTM, 1, 8) AS ED_DT, R.TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(R.TRIP_TYPE_CDS) AS TRIP_TYPE_NM, R.TRIP_PLACE, R.TRIP_DIV, FN_CM05M01_CD_TO_NM(R.TRIP_DIV) AS TRIP_DIV_NM, NVL(D3.EQUIP_NM, R.EQUIP_NM) AS EQUIP_NM, NVL(D3.CLNT_PJT, R.CLNT_PJT) AS CLNT_PJT, NVL(D3.CLNT_PJT_NM, FN_CM05M01_CD_TO_NM(R.CLNT_PJT)) AS CLNT_PJT_NM, NVL(D3.SALES_CD, R.SALES_CD) AS SALES_CD, NVL(D3.ORDRS_NO, R.SALES_CD) AS ORDRS_NO, CAST(NULL AS VARCHAR2(20)) AS VAC_TYPE_CD, CAST(NULL AS VARCHAR2(100)) AS VAC_TYPE_NM, CAST(NULL AS VARCHAR2(20)) AS AMPM_CD, CAST(NULL AS NUMBER) AS WORK_HOUR, M.APRV_STS_CD AS STS FROM TB_CM06M01 U INNER JOIN TB_PM52D02 D ON D.USER_ID = U.ID INNER JOIN TB_PM52M01 M ON M.TRIP_RPT_NO = D.TRIP_RPT_NO LEFT OUTER JOIN TB_PM51M01 R ON R.TRIP_REQ_NO = M.TRIP_REQ_NO LEFT OUTER JOIN ( SELECT TRIP_RPT_NO, ST_DT, ED_DT, EQUIP_NM, CLNT_PJT, CLNT_PJT_NM, SALES_CD, ORDRS_NO, ROW_NUMBER() OVER(PARTITION BY TRIP_RPT_NO, ST_DT, ED_DT ORDER BY SEQ ASC) AS RN FROM TB_PM52D03 WHERE ST_DT <= #{edDt, jdbcType=VARCHAR} AND ED_DT >= #{stDt, jdbcType=VARCHAR} ) D3 ON D3.TRIP_RPT_NO = D.TRIP_RPT_NO AND D3.RN = 1 WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND D.TRIP_ST_DTM <= #{edDt, jdbcType=VARCHAR} || '999999' AND D.TRIP_ED_DTM >= #{stDt, jdbcType=VARCHAR} || '000000'
UNION ALL
-- 2) 출장(복명서 없는 경우: 계획일시, TB_PM51D01 기준, 출장자별 개별행) SELECT /*+ LEADING(U D M D3) USE_NL(D M D3) INDEX(D) PUSH_PRED(D3) */ U.EMP_NO AS EMP_NO, 'TRIP_REQ' AS SRC_TYPE, M.TRIP_REQ_NO AS APPL_NO, CAST(NULL AS VARCHAR2(30)) AS RPT_NO, SUBSTR(D.TRIP_ST_DTM, 1, 8) AS ST_DT, SUBSTR(D.TRIP_ED_DTM, 1, 8) AS ED_DT, M.TRIP_TYPE_CDS, FN_CM05M01_CD_TO_NM(M.TRIP_TYPE_CDS) AS TRIP_TYPE_NM, M.TRIP_PLACE, M.TRIP_DIV, FN_CM05M01_CD_TO_NM(M.TRIP_DIV) AS TRIP_DIV_NM, NVL(D3.EQUIP_NM, M.EQUIP_NM) AS EQUIP_NM, NVL(D3.CLNT_PJT, M.CLNT_PJT) AS CLNT_PJT, NVL(D3.CLNT_PJT_NM, FN_CM05M01_CD_TO_NM(M.CLNT_PJT)) AS CLNT_PJT_NM, NVL(D3.SALES_CD, M.SALES_CD) AS SALES_CD, NVL(D3.ORDRS_NO, M.SALES_CD) AS ORDRS_NO, CAST(NULL AS VARCHAR2(20)) AS VAC_TYPE_CD, CAST(NULL AS VARCHAR2(100)) AS VAC_TYPE_NM, CAST(NULL AS VARCHAR2(20)) AS AMPM_CD, CAST(NULL AS NUMBER) AS WORK_HOUR, M.APRV_STS_CD AS STS FROM TB_CM06M01 U INNER JOIN TB_PM51D01 D ON D.USER_ID = U.ID INNER JOIN TB_PM51M01 M ON M.TRIP_REQ_NO = D.TRIP_REQ_NO LEFT OUTER JOIN ( SELECT TRIP_REQ_NO, ST_DT, ED_DT, EQUIP_NM, CLNT_PJT, CLNT_PJT_NM, SALES_CD, ORDRS_NO, ROW_NUMBER() OVER(PARTITION BY TRIP_REQ_NO, ST_DT, ED_DT ORDER BY SEQ ASC) AS RN FROM TB_PM51D03 WHERE ST_DT <= #{edDt, jdbcType=VARCHAR} AND ED_DT >= #{stDt, jdbcType=VARCHAR} ) D3 ON D3.TRIP_REQ_NO = D.TRIP_REQ_NO AND D3.RN = 1 WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND D.TRIP_ST_DTM <= #{edDt, jdbcType=VARCHAR} || '999999' AND D.TRIP_ED_DTM >= #{stDt, jdbcType=VARCHAR} || '000000' AND NOT EXISTS ( SELECT 1 FROM TB_PM52M01 M2 INNER JOIN TB_PM52D02 D2 ON D2.TRIP_RPT_NO = M2.TRIP_RPT_NO WHERE M2.TRIP_REQ_NO = D.TRIP_REQ_NO AND D2.USER_ID = D.USER_ID )
UNION ALL
-- 3) 휴가 (TB_PM07M01/TB_PM07M03 기준, 일자별) SELECT U.EMP_NO AS EMP_NO, 'VAC' AS SRC_TYPE, M.REQ_NO AS APPL_NO, CAST(NULL AS VARCHAR2(30)) AS RPT_NO, D.VAC_DT AS ST_DT, D.VAC_DT AS ED_DT, CAST(NULL AS VARCHAR2(20)) AS TRIP_TYPE_CDS, CAST(NULL AS VARCHAR2(100)) AS TRIP_TYPE_NM, CAST(NULL AS VARCHAR2(200)) AS TRIP_PLACE, CAST(NULL AS VARCHAR2(20)) AS TRIP_DIV, CAST(NULL AS VARCHAR2(100)) AS TRIP_DIV_NM, CAST(NULL AS VARCHAR2(200)) AS EQUIP_NM, CAST(NULL AS VARCHAR2(30)) AS CLNT_PJT, CAST(NULL AS VARCHAR2(200)) AS CLNT_PJT_NM, CAST(NULL AS VARCHAR2(30)) AS SALES_CD, CAST(NULL AS VARCHAR2(30)) AS ORDRS_NO, M.VAC_TYPE_CD, (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = M.VAC_TYPE_CD) AS VAC_TYPE_NM, M.AMPM_CD, D.WORK_HOUR, M.SANCTN_STS AS STS FROM TB_PM07M03 D INNER JOIN TB_PM07M01 M ON M.CO_CD = D.CO_CD AND M.REQ_NO = D.REQ_NO INNER JOIN TB_CM06M01 U ON U.ID = M.REQ_ID WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND D.VAC_DT >= #{stDt, jdbcType=VARCHAR} AND D.VAC_DT <= #{edDt, jdbcType=VARCHAR}
UNION ALL
-- 4) 휴일대체근무 (TB_PM08M01, HOLIDAY_DT만 — 승인상태 무관하게 매칭, 사용자 확정 사항) SELECT U.EMP_NO AS EMP_NO, 'SUBSTWORK' AS SRC_TYPE, M.REQ_NO AS APPL_NO, CAST(NULL AS VARCHAR2(30)) AS RPT_NO, M.HOLIDAY_DT AS ST_DT, M.HOLIDAY_DT AS ED_DT, CAST(NULL AS VARCHAR2(20)) AS TRIP_TYPE_CDS, CAST(NULL AS VARCHAR2(100)) AS TRIP_TYPE_NM, CAST(NULL AS VARCHAR2(200)) AS TRIP_PLACE, CAST(NULL AS VARCHAR2(20)) AS TRIP_DIV, CAST(NULL AS VARCHAR2(100)) AS TRIP_DIV_NM, CAST(NULL AS VARCHAR2(200)) AS EQUIP_NM, CAST(NULL AS VARCHAR2(30)) AS CLNT_PJT, CAST(NULL AS VARCHAR2(200)) AS CLNT_PJT_NM, CAST(NULL AS VARCHAR2(30)) AS SALES_CD, CAST(NULL AS VARCHAR2(30)) AS ORDRS_NO, CAST(NULL AS VARCHAR2(20)) AS VAC_TYPE_CD, CAST(NULL AS VARCHAR2(100)) AS VAC_TYPE_NM, CAST(NULL AS VARCHAR2(20)) AS AMPM_CD, CAST(NULL AS NUMBER) AS WORK_HOUR, CAST(NULL AS VARCHAR2(20)) AS STS FROM TB_PM08M01 M INNER JOIN TB_CM06M01 U ON U.ID = M.REQ_ID WHERE U.EMP_NO IN
#{item, jdbcType=VARCHAR}
AND M.HOLIDAY_DT >= #{stDt, jdbcType=VARCHAR} AND M.HOLIDAY_DT <= #{edDt, jdbcType=VARCHAR} ) ORDER BY ST_DT ASC

SELECT
	A.WORK_DT,
	A.EMP_NO
FROM TB_PM30M01 A
WHERE A.CO_CD = #{coCd, jdbcType=VARCHAR}
  AND A.WORK_DT >= #{stDt, jdbcType=VARCHAR}
  AND A.WORK_DT <= #{edDt, jdbcType=VARCHAR}

  AND A.EMP_NO IN

	#{item, jdbcType=VARCHAR}
